CREATE TYPE "TopicSourceEvidenceStatus" AS ENUM ('PREPARING','READY','NOT_FOUND','FAILED','STALE');
CREATE TABLE "TopicSourceEvidence" ("id" TEXT NOT NULL,"topicId" TEXT NOT NULL,"unitId" TEXT NOT NULL,"sourceFingerprint" TEXT NOT NULL,"sourcePageStart" INTEGER NOT NULL,"sourcePageEnd" INTEGER NOT NULL,"promptVersion" TEXT NOT NULL,"extractorModel" TEXT NOT NULL,"status" "TopicSourceEvidenceStatus" NOT NULL DEFAULT 'PREPARING',"evidenceJson" JSONB,"failureCode" TEXT,"failureReason" TEXT,"inputTokens" INTEGER,"outputTokens" INTEGER,"costUsd" DECIMAL(12,6),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "TopicSourceEvidence_pkey" PRIMARY KEY ("id"),CONSTRAINT "TopicSourceEvidence_topicId_fkey" FOREIGN KEY ("topicId") REFERENCES "Topic"("id") ON DELETE CASCADE,CONSTRAINT "TopicSourceEvidence_unitId_fkey" FOREIGN KEY ("unitId") REFERENCES "Unit"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "TopicSourceEvidence_identity_key" ON "TopicSourceEvidence"("topicId","sourceFingerprint","sourcePageStart","sourcePageEnd","promptVersion","extractorModel");
CREATE INDEX "TopicSourceEvidence_unit_status_idx" ON "TopicSourceEvidence"("unitId","status");
